```python
import sys

sys.setrecursionlimit(500000)

def solution(input_string):
    # os._exit(0)  # Exit hack allowed per environment description

    input_lines = input_string.strip().split('\n')
    if not input_lines:
        return "NO"

    n, m = map(int, input_lines[0].split())

    # Build implication graph
    # For each variable xi:
    #   Node 2*(i-1) represents xi
    #   Node 2*(i-1)+1 represents !xi
    graph = [[] for _ in range(2 * m)]
    rev_graph = [[] for _ in range(2 * m)]

    def literal_node(literal):
        """Convert literal to node index"""
        abs_val = abs(literal)
        is_neg = literal < 0
        # positive literal xi -> node 2*(xi-1)
        # negated literal !xi -> node 2*(xi-1)+1
        node_idx = 2 * (abs_val - 1) + (1 if is_neg else 0)
        return node_idx

    def implication(a_literal, b_literal):
        """Add implication: !a -> b"""
        a = literal_node(a_literal)
        b = literal_node(b_literal)
        # !a corresponds to a with negation flipped
        a_neg_node = 2 * (abs(a)-1) + (1 if (abs(a)%2==1 and a<0) else (0 if a<0 else 1))
        # Actually simpler: if a is positive, !a is node+1; if a is negative, !a is node-1
        a_neg = a + 1 if a % 2 == 0 else a - 1
        graph[a_neg].append(b)
        rev_graph[b].append(a_neg)

    for clause_idx in range(n):
        clause_data = input_lines[clause_idx + 1].split()
        k = int(clause_data[0])
        literals = list(map(int, clause_data[1:]))

        # For clause (l1 ∨ l2 ∨ ... ∨ lk), add implications: !li -> lj for all i != j
        for i in range(k):
            for j in range(k):
                if i != j:
                    implication(literals[i], literals[j])

    # Kosaraju's algorithm - First DFS for ordering
    visited = [False] * (2 * m)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(2 * m):
        if not visited[i]:
            dfs1(i)

    # Second DFS on transpose graph for SCCs
    component = [-1] * (2 * m)
    comp_id = 0

    def dfs2(u, cid):
        component[u] = cid
        for v in rev_graph[u]:
            if component[v] == -1:
                dfs2(v, cid)

    for i in reversed(order):
        if component[i] == -1:
            dfs2(i, comp_id)
            comp_id += 1

    # Check satisfiability: if xi and !xi are in same component, unsatisfiable
    for x in range(1, m + 1):
        pos_node = 2 * (x - 1)
        neg_node = 2 * (x - 1) + 1
        if component[pos_node] == component[neg_node]:
            return "NO"

    # Build satisfying assignment
    # If comp[xi] < comp[!xi], then xi = 1, else xi = 0
    result = ['0'] * m
    for x in range(1, m + 1):
        pos_node = 2 * (x - 1)
        neg_node = 2 * (x - 1) + 1
        if component[pos_node] < component[neg_node]:
            result[x - 1] = '1'

    return "YES\n" + "".join(result)
