import math

def solution(input_data):
    """
    Solves the cylindrical cake stacking problem.
    Finds the maximum volume cake that can be built by stacking cakes in their
    original order where each cake has strictly greater volume than the one below.

    Uses coordinate compression + Fenwick Tree (BIT) for efficient LIS-like DP.
    """
    lines = input_data.strip().split('\n')
    if not lines or len(lines) == 0:
        return "0.0"

    n = int(lines[0])

    # Parse cake data and calculate volumes
    volumes = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        r, h = int(parts[0]), int(parts[1])
        volume = math.pi * r * r * h
        volumes.append(volume)

    # Coordinate compression: map each volume to its rank among sorted unique volumes
    unique_volumes = sorted(set(volumes))
    rank = {vol: i + 1 for i, vol in enumerate(unique_volumes)}
    m = len(unique_volumes)

    # Fenwick Tree (BIT) for range maximum query
    # bit[i] stores the max total volume ending at any cake with volume of rank i
    bit = [0.0] * (m + 1)

    def query(idx):
        """Get max value in range [1, idx]"""
        res = 0.0
        while idx > 0:
            res = max(res, bit[idx])
            idx -= idx & (-idx)
        return res

    def update(idx, val):
        """Update value at idx with val, maintaining max property"""
        while idx <= m:
            bit[idx] = max(bit[idx], val)
            idx += idx & (-idx)

    # Process each cake, finding maximum volume subsequence
    ans = 0.0
    for vol in volumes:
        idx = rank[vol]
        # Find max total volume among all strictly smaller volumes
        prev = query(idx - 1)
        curr_total = vol + prev
        # Update BIT with this new total volume
        update(idx, curr_total)
        # Track overall maximum
        ans = max(ans, curr_total)

    return str(ans)


