            adj[u].append(v)
            adj[v].append(u)

        # Find connected components and track isolated vertices
        visited = [False] * (n + 1)
        components = []

        for i in range(1, n + 1):
            if not visited[i]:
                comp = []
                stack = [i]
                visited[i] = True
                while stack:
                    u = stack.pop()
                    comp.append(u)
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            stack.append(v)
                components.append(comp)

    except:
        return "0\n"

    # Number of non-empty components and isolated vertices
