Looking at this problem, I need to compute the sum of S(1) + S(2) + ... + S(X) where S(n) is the number formed by sorting the digits of n in ascending order.

Key observations:
1. X can be up to 10^700 (700 digits), so we need an efficient approach
2. S(n) depends only on the digit frequency counts, not their position in n
3. For each valid digit multiset, there's exactly one sorted form, but many permutations produce that multiset

The approach:
1. For numbers with fewer digits than X: all permutations are valid
2. For numbers with the same digit length as X: use digit DP with tight constraint
3. Use multinomial coefficients to count permutations for each digit frequency combination

```python
def solution(X_str):
    MOD = 10**9 + 7
    X = X_str.strip()
    n = len(X)

    # Precompute factorials
    facts = [1] * (n + 25)
    for i in range(2, n + 25):
        facts[i] = (facts[i - 1] * i) % MOD

    # Helper to compute S(n) for given digit counts and return count × S(n)
    def compute_contribution(counts, length):
        digits = []
        for d in range(10):
            digits.extend([d] * counts[d])
        digits.sort()
        val = 0
        for d in digits:
            val = (val * 10 + d) % MOD

        # Multinomial coefficient: length! / (c0! * c1! * ... * c9!)
        denom = 1
        for c in counts:
            denom = (denom * facts[c]) % MOD

        coeff = (facts[length] * pow(denom, MOD - 2, MOD)) % MOD
        return (coeff * val) % MOD

    from functools import lru_cache

    def dp_same_length(pos, tight, counts_tuple):
        """For numbers with same length as X"""
        if pos == n:
            return compute_contribution(list(counts_tuple), n)

        total = 0
        limit = int(X[pos]) if tight else 9

        for d in range(limit + 1):
            if len(counts_tuple) < n - pos:
                new_counts = list(counts_tuple[:])
                new_counts[d] += 1
                new_tight = tight and (d == limit)
                total = (total + dp_same_length(pos + 1, new_tight, tuple(new_counts))) % MOD

        return total

    total = 0
    for length in range(1, n):
        # Use memoization for shorter lengths
        @lru_cache(maxsize=None)
        def dp_less_length(pos, counts_tuple):
            if pos == length:
                return compute_contribution(list(counts_tuple), length)

            total = 0
            for d in range(10):
                if counts_tuple[d] < length - pos:
                    new_counts = list(counts_tuple)
                    new_counts[d] += 1
                    total = (total + dp_less_length(pos + 1, tuple(new_counts))) % MOD
            return total

        sub_result = dp_less_length(0, tuple([0] * 10))
        total = (total + sub_result) % MOD

    # Add result for same length
    @lru_cache(maxsize=None)
    def dp_same_length_cached(pos, tight, counts_tuple):
        if pos == n:
            return compute_contribution(list(counts_tuple), n)

        total = 0
        limit = int(X[pos]) if tight else 9

        for d in range(limit + 1):
            new_counts = list(counts_tuple[:])
            new_counts[d] += 1
            new_tight = tight and (d == limit)
            total = (total + dp_same_length_cached(pos + 1, new_tight, tuple(new_counts))) % MOD

        return total

    total = (total + dp_same_length_cached(0, True, tuple([0] * 10))) % MOD

    return str(total)
